const $=id=>document.getElementById(id);
const params=new URLSearchParams(location.search);
const inviteToken=params.get('invite');
const steps=['Your details','Plan & price','Agreement','Payment'];
let enrollment=null;
let customerStep=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
function message(id,text,error=false){$(id).textContent=text;$(id).classList.toggle('error',error)}
function showAdmin(){ $('admin-view').hidden=false;$('customer-view').hidden=true;loadQueue(); }
function showCustomer(){ $('admin-view').hidden=true;$('customer-view').hidden=false; }

$('new-invite').addEventListener('click',async()=>{try{const r=await api('/api/admin/invitations','POST',{});const url=new URL(r.inviteUrl,location.origin).href;$('invite-result').hidden=false;$('invite-result').innerHTML=`<h2>Invitation ready</h2><p>Local invitation created. No email was sent.</p><label for="invite-link">Copy this customer link</label><input id="invite-link" class="invite-url" readonly value="${esc(url)}"><div class="actions"><button id="copy-link" class="secondary">Copy invitation link</button><a class="button primary" href="${esc(url)}" target="_blank" rel="noopener">Open customer view</a></div>`;$('copy-link').onclick=async()=>{await navigator.clipboard.writeText(url);message('admin-message','Invitation link copied.');};message('admin-message','Invitation created for captain-invited enrollment.');}catch(e){message('admin-message',e.message,true);}});
$('refresh').addEventListener('click',loadQueue);

async function loadQueue(){try{const all=await api('/api/admin/enrollments');const queue=$('queue');if(!all.length){queue.innerHTML='<p class="lede">No enrollments yet. Create an invitation to start a synthetic customer flow.</p>';return;}queue.innerHTML=all.slice().reverse().map(e=>`<article class="queue-item"><div><h3>${esc(e.questionnaire?.ownerName||'Invited customer')}</h3><div>${esc(e.questionnaire?.vesselName||'Vessel pending')} · ${esc(e.selection?.plan||'Plan pending')}</div><small>Payment: ${esc(e.paymentStatus)} · HYC: ${esc(e.hycDecision)} · Service: ${esc(e.serviceReadiness)}</small></div><button class="secondary" data-review="${esc(e.id)}">Open review</button></article>`).join('');queue.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openReview(b.dataset.review));}catch(e){message('admin-message',e.message,true);}}

async function openReview(id){try{const e=await api(`/api/admin/enrollments/${id}`);const q=e.questionnaire||{};const box=$('review');box.hidden=false;box.innerHTML=`<p class="eyebrow">CAPTAIN WILL REVIEW</p><h2>${esc(q.ownerName||'Customer')} · ${esc(q.vesselName||'Vessel')}</h2><div class="warning">Customer has paid; HYC acceptance is pending. Payment is not HYC acceptance or a fully executed agreement.</div><dl class="summary"><dt>Contact</dt><dd>${esc(q.ownerEmail)} · ${esc(q.ownerPhone)}</dd><dt>Vessel</dt><dd>${esc(q.vesselModel)} · ${esc(q.loa)} ft · $${esc(q.value)}</dd><dt>Location</dt><dd>${esc(q.marina)} · ${esc(q.slip)}</dd><dt>Insurance</dt><dd>${esc(q.insurer)} · expires ${esc(q.policyExpiry)}</dd><dt>Hazards / restrictions</dt><dd>${esc(q.hazards||'None supplied')}</dd><dt>Requested checks</dt><dd>${(q.requestedChecks||[]).map(esc).join(', ')||'None selected'}</dd><dt>Emergency authority</dt><dd>Cap $${esc(q.emergencyCap||0)} · contact ${esc(q.emergencyName)} / ${esc(q.emergencyPhone)}</dd><dt>Plan / billing</dt><dd>${esc(e.selection?.plan)} · ${esc(e.selection?.visitFrequency)} visits · ${esc(e.selection?.cadence)} · $${esc(e.selection?.amount)} ${e.selection?.cadence==='Annual'?'per year':'per month'}</dd><dt>Payment</dt><dd>${esc(e.paymentStatus)} at ${esc(e.paidAt||'—')} · next anniversary ${esc(e.nextBillingAt||'—')}</dd><dt>Customer signature</dt><dd>${esc(e.signers.customer)} at ${esc(e.signedAt||'—')}</dd><dt>Agreement</dt><dd>TEST DOCUMENT — NOT LEGALLY BINDING</dd></dl>${e.hycDecision==='review_pending'?`<div class="review-actions"><button class="primary" id="accept">Countersign & accept</button><button class="secondary" id="decline">Decline enrollment</button></div>`:e.hycDecision==='accepted'?`<h3>Post-acceptance setup</h3><p>Keep Boat Binder, operational onboarding, and service scheduling separate.</p><label><input type="checkbox" data-ready="boatBinder" ${e.boatBinder?'checked':''}> Boat Binder setup complete</label><br><label><input type="checkbox" data-ready="operationalOnboarding" ${e.operationalOnboarding?'checked':''}> Operational onboarding complete</label><br><label><input type="checkbox" data-ready="firstVisit" ${e.firstVisit?'checked':''}> First visit scheduled</label><p>Readiness: <strong>${esc(e.serviceReadiness)}</strong></p>`:`<p>HYC decision: ${esc(e.hycDecision)} · refund: ${esc(e.refundStatus)}</p>`}`;
if($('accept'))$('accept').onclick=()=>decide(id,'accept');if($('decline'))$('decline').onclick=()=>decide(id,'decline');box.querySelectorAll('[data-ready]').forEach(c=>c.onchange=()=>setReady(id,c.dataset.ready,c.checked));box.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){message('admin-message',e.message,true);}}
async function decide(id,decision){try{await api(`/api/admin/enrollments/${id}/decision`,'POST',{decision});message('admin-message',decision==='accept'?'HYC acceptance and simulated countersignature recorded.':'Decline recorded; simulated cancellation and manual-refund-pending created.');await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}
async function setReady(id,step,done){try{await api(`/api/admin/enrollments/${id}/readiness`,'POST',{step,done});await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}

function stepBar(){ $('progress').innerHTML=steps.map((s,i)=>`<span ${i===customerStep?'aria-current="step"':''}>${i+1}. ${s}</span>`).join(''); }
function questionnaireForm(){return `<h2>Tell us about you and your vessel</h2><p>Use fictional details for this prototype. HYC will prepare the agreement from your responses.</p><form id="questionnaire" class="form-grid">
${field('ownerName','Legal owner / contracting party','text',true)}${field('signerAuthority','Signer title / authority to bind (or owner)','text',true)}${field('ownerEmail','Email','email',true)}${field('ownerPhone','Phone','tel',true)}${field('reportEmail','Report email','email',true)}
${field('vesselName','Vessel name','text',true)}${field('vesselModel','Year / make / model','text',true)}${field('loa','Length overall (30–60 ft)','number',true)}${field('value','Approximate vessel value (max $1.5M)','number',true)}${field('hin','HIN / registration (optional)','text',false)}
${field('marina','Marina','text',true)}${field('slip','Dock / slip','text',true)}${field('insurer','Marine insurer','text',true)}${field('policyExpiry','Policy expiration','date',true)}
${field('emergencyName','Emergency contact','text',true)}${field('emergencyPhone','Emergency contact phone','tel',true)}${field('emergencyCap','Emergency spending cap ($0 if blank)','number',false)}
${field('hazards','Access limitations, hazards, and do-not-operate notes','textarea',false,true)}<div class="field full"><label><input type="checkbox" name="confirmAuthority" required> I confirm I own the vessel or can bind the contracting party.</label></div><div class="field full"><label><input type="checkbox" name="insuranceConfirmed" required> I confirm current appropriate marine insurance is maintained and proof can be provided on request.</label></div><fieldset class="field full"><legend>Requested visual checks (permissions require signed Exhibit A)</legend><div class="checks">${['Exterior / dock lines','Shore-power display','Visible bilge / leaks','Battery display','Cabin climate','Plumbing / sanitation','Engine/generator visual only','Photos / reports'].map(x=>`<label><input type="checkbox" name="requestedChecks" value="${esc(x)}"> ${esc(x)}</label>`).join('')}</div></fieldset><div class="warning field full">Do not enter access codes, alarm PINs, passwords, payment card data, or real customer information.</div><div class="actions field full"><button class="primary">Continue to plan & pricing</button></div></form>`;}
function field(name,label,type,required,full=false){return `<div class="field ${full?'full':''}"><label for="${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" ${required?'required':''}></textarea>`:`<input id="${name}" name="${name}" type="${type}" ${required?'required':''} ${type==='number'?(name==='loa'?'min="30" max="60" step="1"':'min="0" max="1500000" step="1"'):''}>`}</div>`;}
function planForm(){return `<h2>Choose a service plan</h2><form id="plan-form" class="form-grid"><div class="field"><label for="plan">Plan</label><select id="plan" name="plan"><option>Dock Check</option><option>Dock Watch</option><option>Dock Watch Plus</option></select></div><div class="field"><label for="frequency">Visit frequency</label><select id="frequency" name="frequency"></select></div><div class="field"><label for="billing">Billing interval</label><select id="billing" name="billing"><option>Monthly</option><option>Annual</option></select></div><div class="field full"><label>Price preview</label><p id="price-preview" class="price"></p><small>Annual billing is prepaid at 10% off twelve monthly equivalents. Anniversary billing follows the first successful simulated charge.</small></div><div class="actions field full"><button class="secondary" type="button" id="back-details">Back</button><button class="primary">Review sample agreement</button></div></form>`;}
function agreementView(){const q=enrollment.questionnaire,p=enrollment.selection;return `<h2>Review your sample agreement</h2><div class="terms"><p class="terms-stamp">TEST DOCUMENT — NOT LEGALLY BINDING</p><h3>Hayes Yacht Company · Sample Vessel Watch Agreement</h3><p>This fictional preview is only a workflow demonstration, not an HYC offer or contract.</p><p><b>Customer:</b> ${esc(q.ownerName)} · ${esc(q.ownerEmail)}<br><b>Vessel:</b> ${esc(q.vesselName)}, ${esc(q.vesselModel)}, ${esc(q.loa)} ft<br><b>Plan:</b> ${esc(p.plan)} · ${esc(p.visitFrequency)} checks · ${esc(p.cadence)} billing<br><b>Simulated charge:</b> $${esc(p.amount)} ${p.cadence==='Annual'?'annual prepayment':'monthly'}<br><b>Requested checks:</b> ${q.requestedChecks.map(esc).join(', ')||'No checks selected'}<br><b>Emergency cap:</b> $${esc(q.emergencyCap||0)}</p><p>Customer signs first. After the customer signs, they proceed to simulated checkout immediately. Captain Will reviews and countersigns afterward. Payment does not mean HYC has accepted or fully executed an agreement. No vessel operation or payment authorization is created.</p><p>Annual prepayment/refunds, service commencement, Effective Date, and HYC acceptance require legal review. Source agreement Section 10.4 remains unchanged in the separate review draft.</p><p class="terms-stamp">TEST DOCUMENT — NOT LEGALLY BINDING</p></div><form id="sign-form"><label><input required type="checkbox"> I reviewed this sample and want to simulate my customer signature.</label><div class="actions" style="margin-top:18px"><button class="secondary" type="button" id="back-plan">Back</button><button class="primary">Simulate customer signature & continue</button></div></form>`;}
function paymentView(){return `<h2>Simulated subscription checkout</h2><div class="success"><b>Customer signature recorded in mock mode.</b> You can finish payment in this same session. Captain Will's countersignature is pending and is not required to continue.</div><p class="price">$${esc(enrollment.selection.amount)} <small>${enrollment.selection.cadence==='Annual'?'annual prepaid':'monthly'}</small></p><p>Simulated payment only. No Stripe request or payment method is involved.</p><div class="actions"><button class="primary" data-payment="succeeded">Simulate successful payment</button><button class="secondary" data-payment="failed">Simulate failed payment</button><button class="secondary" data-payment="abandoned">Simulate checkout abandoned</button></div>${enrollment.paymentStatus==='failed'||enrollment.paymentStatus==='abandoned'?'<p class="message error">Payment did not complete. You can retry here without returning later.</p>':''}`;}
function statusView(){if(enrollment.hycDecision==='accepted')return `<h2>HYC accepted your enrollment</h2><div class="success">Your sample agreement is fully executed in this simulation. Captain Will will follow up with Boat Binder setup, operational onboarding, and first-visit scheduling.</div><p>Service readiness: ${esc(enrollment.serviceReadiness)}. This is not a production confirmation.</p><button id="refresh-customer" class="secondary">Refresh status</button>`;if(enrollment.hycDecision==='declined')return `<h2>HYC did not accept this enrollment</h2><div class="warning">The simulated subscription is canceled. A manual refund is pending; no automatic refund was issued.</div><button id="refresh-customer" class="secondary">Refresh status</button>`;return `<h2>Payment received</h2><div class="success"><b>Your customer enrollment is complete.</b> Payment is recorded in this simulation; agreement is pending HYC acceptance and Captain Will's countersignature.</div><p>Captain Will will review the information and sign second. You do not need to return to complete your portion.</p><p>Payment timestamp: ${esc(enrollment.paidAt)}<br>Next billing anniversary: ${esc(enrollment.nextBillingAt)}</p><button id="refresh-customer" class="secondary">Refresh HYC review status</button>`;}

async function loadCustomer(){showCustomer();try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}`);renderCustomer();}catch(e){message('customer-alert',e.message,true);$('step-content').innerHTML='<p>This invitation is invalid or expired. Ask Captain Will for a new local invitation.</p>';}}
function renderCustomer(){stepBar();let content;if(!enrollment.questionnaire){customerStep=0;content=questionnaireForm();}else if(!enrollment.selection){customerStep=1;content=planForm();}else if(enrollment.agreementStatus==='awaiting_customer'){customerStep=2;content=agreementView();}else if(enrollment.paymentStatus!=='succeeded'&&enrollment.hycDecision!=='accepted'&&enrollment.hycDecision!=='declined'){customerStep=3;content=paymentView();}else{customerStep=3;content=statusView();}$('progress').innerHTML=steps.map((s,i)=>`<span ${i===customerStep?'aria-current="step"':''}>${i+1}. ${s}</span>`).join('');$('step-content').innerHTML=content;bindCustomer();}
function bindCustomer(){
const qform=$('questionnaire');if(qform)qform.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(qform);const body=Object.fromEntries(fd.entries());body.requestedChecks=fd.getAll('requestedChecks');try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/questionnaire`,'POST',body);renderCustomer();}catch(e){message('customer-alert',e.message,true);}};
const pform=$('plan-form');if(pform){const frequency=$('frequency'),billing=$('billing'),plan=$('plan');const opts=()=>{const map={'Dock Check':['Every two weeks','Weekly'],'Dock Watch':['Monthly','Every two weeks','Weekly'],'Dock Watch Plus':['Weekly']};frequency.innerHTML=map[plan.value].map(x=>`<option>${x}</option>`).join('');preview();};const preview=()=>{const band=Number(enrollment.questionnaire.loa)<=39?0:Number(enrollment.questionnaire.loa)<=49?1:2;const map={'Dock Check':{'Every two weeks':[99,99,99],Weekly:[159,159,159]},'Dock Watch':{Monthly:[129,149,169],'Every two weeks':[179,209,239],Weekly:[239,279,319]},'Dock Watch Plus':{Weekly:[399,449,499]}};const v=map[plan.value][frequency.value][band];$('price-preview').textContent=billing.value==='Annual'?`$${(v*12*.9).toFixed(2)} / year (10% off $${v}/mo)`:`$${v} / month`;};plan.onchange=opts;frequency.onchange=preview;billing.onchange=preview;opts();$('back-details').onclick=()=>{enrollment.questionnaire=null;renderCustomer();};pform.onsubmit=async ev=>{ev.preventDefault();try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/plan`,'POST',{plan:plan.value,visitFrequency:frequency.value,billingCadence:billing.value});renderCustomer();}catch(e){message('customer-alert',e.message,true);}};}
const sform=$('sign-form');if(sform)sform.onsubmit=async ev=>{ev.preventDefault();try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/sign`,'POST',{});renderCustomer();}catch(e){message('customer-alert',e.message,true);}};
document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/payment`,'POST',{outcome:b.dataset.payment});renderCustomer();}catch(e){message('customer-alert',e.message,true);b.disabled=false;}});
if($('back-plan'))$('back-plan').onclick=()=>{enrollment.selection=null;renderCustomer();};if($('refresh-customer'))$('refresh-customer').onclick=async()=>{try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}`);renderCustomer();}catch(e){message('customer-alert',e.message,true);}};
}

if(inviteToken)loadCustomer();else showAdmin();
